// Read-only archive access with libarchive compiled to WebAssembly (7z, RAR 4/5, tar.*, xz, bz2, CAB, ISO 9660,
// CPIO, AR/deb, LHA, ZIP, ...). libarchive.js/.wasm are generated by scripts/build-libarchive-wasm.mjs from
// wasm/libarchive/wrapper.c; types and documentation are in libarchive-reader.d.ts.
import createLibarchiveModule from './libarchive.js';

// Bits of ar_entry_flags() in wrapper.c.
const FLAG_ENCRYPTED = 1;
const FLAG_SIZE_SET = 2;
const FLAG_MTIME_SET = 4;
const FLAG_RAW_PATH = 8;
const FLAG_HARDLINK = 16;

/** The archive is copied into WebAssembly memory in pieces of this size by openBlob(). */
const BLOB_CHUNK = 16 * 1024 * 1024;

const utf8 = new TextDecoder();
const strictUtf8 = new TextDecoder('utf-8', { fatal: true });
const encoder = new TextEncoder();

// Bytes 0x80-0xFF of code page 437, the charset of ZIP (and old RAR) names without the UTF-8 flag.
const CP437_HIGH =
  'ÇüéâäàåçêëèïîìÄÅÉæÆôöòûùÿÖÜ¢£¥₧ƒáíóúñÑªº¿⌐¬½¼¡«»░▒▓│┤╡╢╖╕╣║╗╝╜╛┐└┴┬├─┼╞╟╚╔╩╦╠═╬╧╨╤╥╙╘╒╓╫╪┘┌█▄▌▐▀' +
  'αßΓπΣσµτΦΘΩδ∞φε∩≡±≥≤⌠⌡÷≈°∙·√ⁿ²■ ';

export class LibarchiveError extends Error {
  constructor(message, code = errorCode(message), options) {
    super(message, options);
    this.name = 'LibarchiveError';
    this.code = code;
  }
}

function errorCode(message) {
  if (/unrecognized archive format|the file is empty/i.test(message)) return 'UNRECOGNIZED';
  if (/passphrase required|incorrect passphrase/i.test(message)) return 'PASSPHRASE';
  if (/encrypt|decrypt/i.test(message)) return 'UNSUPPORTED_ENCRYPTION';
  if (/out of memory|no memory|cannot allocate|too large/i.test(message)) return 'OUT_OF_MEMORY';
  return 'ERROR';
}

function toBytes(data) {
  if (data instanceof Uint8Array) return data;
  if (ArrayBuffer.isView(data)) return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
  if (data instanceof ArrayBuffer || (typeof SharedArrayBuffer !== 'undefined' && data instanceof SharedArrayBuffer)) {
    return new Uint8Array(data);
  }
  throw new TypeError('Archive data must be a Uint8Array or ArrayBuffer');
}

/** Names that are not valid UTF-8 come from old archivers; guess their charset from the format. */
function decodeLegacyName(bytes, format) {
  if (/zip|rar/i.test(format)) {
    let out = '';
    for (const b of bytes) out += b < 0x80 ? String.fromCharCode(b) : CP437_HIGH[b - 0x80];
    return out;
  }
  return new TextDecoder('windows-1252').decode(bytes);
}

/**
 * Loads the WebAssembly module. Every reader has its own memory; drop the reader to give that memory back
 * (WebAssembly memory only grows).
 */
export async function createReader(options = {}) {
  const moduleOptions = {};
  if (options.locateFile) moduleOptions.locateFile = options.locateFile;
  if (options.wasmBinary) moduleOptions.wasmBinary = options.wasmBinary;
  if (options.wasmModule) {
    moduleOptions.instantiateWasm = (imports, done) => {
      WebAssembly.instantiate(options.wasmModule, imports).then((instance) => done(instance, options.wasmModule));
      return {};
    };
  }
  const module = await createLibarchiveModule(moduleOptions);
  return new Reader(module);
}

class Reader {
  #m;
  #crash = null;
  #finalizer = new FinalizationRegistry((handle) => {
    if (!this.#crash) this.#m._ar_close(handle);
  });

  constructor(module) {
    this.#m = module;
  }

  list(data, passphrase) {
    const archive = this.open(data, passphrase);
    try {
      return [...archive.entries];
    } finally {
      archive.close();
    }
  }

  extract(data, index, passphrase) {
    const archive = this.open(data, passphrase);
    try {
      return archive.extract(index);
    } finally {
      archive.close();
    }
  }

  open(data, passphrase) {
    const bytes = toBytes(data);
    const pointer = this.#alloc(bytes.length);
    this.#m.HEAPU8.set(bytes, pointer);
    return this.#open(pointer, bytes.length, passphrase);
  }

  async openBlob(blob, passphrase) {
    const size = blob.size;
    const pointer = this.#alloc(size);
    try {
      for (let offset = 0; offset < size; offset += BLOB_CHUNK) {
        const chunk = new Uint8Array(await blob.slice(offset, Math.min(size, offset + BLOB_CHUNK)).arrayBuffer());
        this.#check();
        this.#m.HEAPU8.set(chunk, pointer + offset);
      }
    } catch (err) {
      if (!this.#crash) this.#m._free(pointer);
      throw err;
    }
    return this.#open(pointer, size, passphrase);
  }

  #check() {
    if (this.#crash) {
      throw new LibarchiveError('libarchive stopped working after an earlier error; create a new reader', 'CRASHED', { cause: this.#crash });
    }
  }

  /** Runs fn; a trap or abort inside WebAssembly leaves the module unusable, so the reader is retired. */
  #call(fn) {
    this.#check();
    try {
      return fn();
    } catch (err) {
      if (err instanceof LibarchiveError) throw err;
      this.#crash = err;
      throw new LibarchiveError(`libarchive crashed: ${err?.message ?? err}`, 'CRASHED', { cause: err });
    }
  }

  #alloc(size) {
    const pointer = this.#call(() => this.#m._malloc(Math.max(size, 1)) >>> 0);
    if (!pointer) throw new LibarchiveError(`Out of memory: ${size} bytes do not fit into WebAssembly memory`, 'OUT_OF_MEMORY');
    return pointer;
  }

  #string(text) {
    const bytes = encoder.encode(text);
    const pointer = this.#alloc(bytes.length + 1);
    this.#m.HEAPU8.set(bytes, pointer);
    this.#m.HEAPU8[pointer + bytes.length] = 0;
    return pointer;
  }

  #bytesAt(pointer) {
    const heap = this.#m.HEAPU8;
    const end = heap.indexOf(0, pointer);
    return heap.slice(pointer, end < 0 ? heap.length : end);
  }

  #text(pointer) {
    return pointer ? this.#m.UTF8ToString(pointer) : '';
  }

  /** Lists the archive at `pointer` (ownership passes to the wrapper) and returns the archive object. */
  #open(pointer, size, passphrase) {
    const m = this.#m;
    const handle = this.#call(() => {
      let pass = 0;
      try {
        if (passphrase) pass = this.#string(passphrase);
      } catch (err) {
        m._free(pointer);
        throw err;
      }
      try {
        return m._ar_open(pointer, size, pass) >>> 0;
      } finally {
        if (pass) m._free(pass);
      }
    });
    if (!handle) throw new LibarchiveError('Out of memory', 'OUT_OF_MEMORY');

    let entries;
    let format;
    let filters;
    let warning;
    try {
      this.#call(() => {
        const error = m._ar_error(handle) >>> 0;
        if (error) throw new LibarchiveError(this.#text(error));
        format = this.#text(m._ar_format(handle) >>> 0);
        const filterList = this.#text(m._ar_filters(handle) >>> 0);
        filters = filterList ? filterList.split(',') : [];
        const warningPointer = m._ar_warning(handle) >>> 0;
        warning = warningPointer ? this.#text(warningPointer) : null;
        entries = this.#readEntries(handle, format);
      });
    } catch (err) {
      if (!this.#crash) m._ar_close(handle);
      throw err;
    }

    const reader = this;
    const token = {};
    let closed = false;
    const byIndex = new Map(entries.map((e) => [e.index, e]));
    const archive = {
      format,
      filters,
      warning,
      entries: entries.map(({ index, path, rawPath, size: entrySize, mtime, encrypted }) =>
        Object.freeze(rawPath ? { index, path, size: entrySize, mtime, encrypted, rawPath } : { index, path, size: entrySize, mtime, encrypted })),
      extract(index, extractPassphrase) {
        if (closed) throw new LibarchiveError('The archive is closed', 'ERROR');
        const entry = byIndex.get(index);
        if (!entry) throw new LibarchiveError(`No file with index ${index} in this archive`, 'ERROR');
        return reader.#extract(handle, entry.dataIndex, extractPassphrase);
      },
      close() {
        if (closed) return;
        closed = true;
        reader.#finalizer.unregister(token);
        if (!reader.#crash) m._ar_close(handle);
      },
    };
    Object.freeze(archive.entries);
    Object.freeze(archive.filters);
    // Safety net for archives that are never closed; close() is still the way to free memory promptly.
    this.#finalizer.register(archive, handle, token);
    return Object.freeze(archive);
  }

  #readEntries(handle, format) {
    const m = this.#m;
    const count = m._ar_count(handle) >>> 0;
    const entries = [];
    for (let i = 0; i < count; i++) {
      const flags = m._ar_entry_flags(handle, i);
      const pathBytes = this.#bytesAt(m._ar_entry_path(handle, i) >>> 0);
      let path;
      let rawPath;
      if (flags & FLAG_RAW_PATH) {
        try {
          path = strictUtf8.decode(pathBytes);
        } catch {
          path = decodeLegacyName(pathBytes, format);
          rawPath = pathBytes;
        }
      } else {
        path = utf8.decode(pathBytes);
      }
      const index = m._ar_entry_header(handle, i) >>> 0;
      entries.push({
        index,
        dataIndex: index,
        path,
        rawPath,
        size: flags & FLAG_SIZE_SET ? m._ar_entry_size(handle, i) : null,
        mtime: flags & FLAG_MTIME_SET ? m._ar_entry_mtime(handle, i) : null,
        encrypted: (flags & FLAG_ENCRYPTED) !== 0,
        hardlink: flags & FLAG_HARDLINK ? this.#text(m._ar_entry_hardlink(handle, i) >>> 0) : null,
      });
    }
    // tar and cpio store the data of hard-linked files once; point the empty links at the copy with data.
    const byPath = new Map();
    for (const entry of entries) if (!entry.hardlink) byPath.set(entry.path, entry);
    for (const entry of entries) {
      const target = entry.hardlink ? byPath.get(entry.hardlink) : undefined;
      if (target && !entry.size) {
        entry.size = target.size;
        entry.dataIndex = target.index;
      }
    }
    return entries;
  }

  #extract(handle, index, passphrase) {
    const m = this.#m;
    return this.#call(() => {
      if (passphrase) {
        const pass = this.#string(passphrase);
        const ok = m._ar_add_passphrase(handle, pass);
        m._free(pass);
        if (ok !== 0) throw new LibarchiveError(this.#text(m._ar_error(handle) >>> 0));
      }
      const pointer = m._ar_extract(handle, index) >>> 0;
      if (!pointer) throw new LibarchiveError(this.#text(m._ar_error(handle) >>> 0));
      const size = m._ar_extracted_size(handle) >>> 0;
      const result = m.HEAPU8.slice(pointer, pointer + size);
      m._free(pointer);
      return result;
    });
  }
}
